// post-regen patch cli-sdk/scripts/post-regen/08-sdk-json-numbers.patch
// calls from unmarshalValue in json.go. Files without the "Code generated by
// Speakeasy" header are not re-emitted on regen, so the helpers survive
// automatically; only the two call sites inside json.go need re-applying.
// See cli-sdk/PRESERVED_EDITS.md.

package utils

import (
	"bytes"
	"encoding/json"
	"reflect"
)

// unmarshalFreeFormMap decodes a JSON object into a map[string]any-shaped
// value with json.Decoder.UseNumber, so integers above 2^53 and long decimals
// survive as json.Number (which encoding/json re-emits verbatim) instead of
// being rounded through float64. The generated code reached this case with a
// plain json.Unmarshal: `perpetual-trading execute --action` and
// `tokenized-assets order-submit --signed-order` turned 12345678901234567890
// into 12345678901234567000 on the wire, and the same happened to the
// `typed_data` / `action` / `order_message` objects of responses on their way
// to pretty, yaml and toon output.
func unmarshalFreeFormMap(value json.RawMessage, v reflect.Value) error {
	dec := json.NewDecoder(bytes.NewReader(value))
	dec.UseNumber()
	if v.CanAddr() {
		return dec.Decode(v.Addr().Interface())
	}
	return dec.Decode(v.Interface())
}

// isJSONNumberLiteral reports whether value is a bare JSON number token
// (not a quoted string, not null, not an object).
func isJSONNumberLiteral(value json.RawMessage) bool {
	trimmed := bytes.TrimSpace(value)
	if len(trimmed) == 0 {
		return false
	}
	// A JSON number starts with a digit or a minus sign; this also rules out
	// null, true/false, strings, objects and arrays before the full check.
	if c := trimmed[0]; c != '-' && (c < '0' || c > '9') {
		return false
	}
	var n json.Number
	return json.Unmarshal(trimmed, &n) == nil
}

// setStringFromNumber stores a bare JSON number's exact lexeme into a
// string-kinded target (string, a named enum type, or a pointer to either).
// Every Decimal amount in this API is a string field on the CLI side (see
// api/scripts/speakeasy_and_combined_spec/prepare_openapi_spec_for_cli.py),
// and raw JSON given through --body, --actions or a union flag may still
// carry `"amount": 0.123456789012345678` as a number. encoding/json would
// reject a number aimed at a string; forwarding the lexeme keeps the request
// valid and exact.
func setStringFromNumber(value json.RawMessage, v reflect.Value, typ reflect.Type) {
	if v.Kind() == reflect.Ptr {
		if v.IsNil() {
			v.Set(reflect.New(typ))
		}
		v = v.Elem()
	}
	v.SetString(string(bytes.TrimSpace(value)))
}
